package com.huy.enterprise.audit; import com.huy.enterprise.user.User; import jakarta.persistence.*; import lombok.*; import java.time.OffsetDateTime; import java.util.UUID; @Getter @Setter @Entity @Table(name="audit_logs") public class AuditLog {@Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="actor_user_id") private User actorUser; @Column(nullable=false,length=100) private String action; @Column(name="entity_type",nullable=false,length=100) private String entityType; @Column(name="entity_id") private UUID entityId; private String description; @Column(name="created_at",nullable=false,updatable=false) private OffsetDateTime createdAt; @PrePersist void prePersist(){createdAt=OffsetDateTime.now();}}
